    // src/components/Flowers.js
    import React, { useEffect, useState } from "react";
    import axios from "axios";
    import { toast } from "react-toastify";
    import "./Flowers.css";

    function Flowers() {
    const [flowers, setFlowers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [imageLoading, setImageLoading] = useState({});

    // ✅ Base API from .env
    const API_BASE = process.env.REACT_APP_API_URL;

    // Fetch all flowers
    useEffect(() => {
        const fetchFlowers = async () => {
        try {
            const res = await axios.get(`${API_BASE}/api/flowers`);
            setFlowers(res.data || []);

            // initialize image loaders
            const initialLoadingState = {};
            res.data.forEach((f) => {
            initialLoadingState[f._id] = true;
            });
            setImageLoading(initialLoadingState);
        } catch (err) {
            console.error("Error fetching flowers:", err);
            toast.error("Failed to load flowers.");
        } finally {
            setLoading(false);
        }
        };

        fetchFlowers();
    }, [API_BASE]);

    // Delete a flower
    const handleDelete = async (id) => {
        if (!window.confirm("Are you sure you want to delete this flower?")) return;

        try {
        await axios.delete(`${API_BASE}/api/flowers/${id}`);
        toast.success("Flower deleted successfully");
        setFlowers((prev) => prev.filter((flower) => flower._id !== id));
        } catch (err) {
        console.error("Error deleting flower:", err);
        toast.error("Failed to delete flower.");
        }
    };

    if (loading) {
        return <p>Loading flowers...</p>;
    }

    return (
        <div className="flowers-container">
        <h2 className="admin-header">🌸 Admin: Manage Flowers</h2>

        <div className="flowers-list">
            {flowers.length === 0 ? (
            <p>No flowers available.</p>
            ) : (
            flowers.map((flower) => {
                // ✅ Build optimized Cloudinary URL for fast loading
                let optimizedUrl = flower.image;
                if (optimizedUrl && optimizedUrl.includes("/upload/")) {
                optimizedUrl = optimizedUrl.replace(
                    "/upload/",
                    "/upload/w_400,h_400,c_fill,q_auto,f_auto/"
                );
                }

                return (
                <div className="flower-card" key={flower._id}>
                    <div className="flower-image">
                    {optimizedUrl ? (
                        <>
                        {imageLoading[flower._id] && (
                            <div className="image-placeholder">
                            <div className="spinner"></div>
                            </div>
                        )}
                        <img
                            src={optimizedUrl}
                            alt={flower.name}
                            loading="lazy"
                            className="flower-img"
                            style={{
                            display: imageLoading[flower._id] ? "none" : "block",
                            }}
                            onLoad={() =>
                            setImageLoading((prev) => ({
                                ...prev,
                                [flower._id]: false,
                            }))
                            }
                            onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = "/placeholder.png";
                            setImageLoading((prev) => ({
                                ...prev,
                                [flower._id]: false,
                            }));
                            }}
                        />
                        </>
                    ) : (
                        <div className="image-placeholder">No Image Available</div>
                    )}
                    </div>

                    <div className="flower-details">
                    <h3>{flower.name}</h3>
                    <p>{flower.description}</p>
                    <p>
                        <span className="label">Category:</span> {flower.category}
                    </p>
                    <p>
                        <span className="label">Price:</span> ${flower.price}
                    </p>

                    <button
                        className="delete-btn"
                        onClick={() => handleDelete(flower._id)}
                    >
                        Delete
                    </button>
                    </div>
                </div>
                );
            })
            )}
        </div>
        </div>
    );
    }

    export default Flowers;
